# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GENETİK MÜHENDİSLİĞİ VE BİYOTEKNOLOJİ İLİŞKİSİ</text>\n  <rect x="30" y="48" width="295" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="177" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">GENETİK MÜHENDİSLİĞİ (Yöntem)</text>\n  <text x="45" y="98" font-size="12" fill="#1e3a8a">• DNA dizilimini ve gen yapısını inceler.</text>\n  <text x="45" y="120" font-size="12" fill="#1e3a8a">• Gen izolasyonu ve kesimi yapar.</text>\n  <text x="45" y="142" font-size="12" fill="#1e3a8a">• Rekombinant DNA (rDNA) oluşturur.</text>\n  <text x="45" y="164" font-size="12" fill="#1e3a8a">• Gen klonlaması ve gen aktarımı yapar.</text>\n  <rect x="45" y="182" width="265" height="42" rx="6" fill="#eff6ff" stroke="#60a5fa" stroke-width="1.5"/>\n  <text x="177" y="207" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Odak: Gen düzeyinde moleküler müdahale</text>\n  <line x1="325" y1="143" x2="365" y2="143" stroke="#0f172a" stroke-width="2.5"/>\n  <polygon points="365,137 377,143 365,149" fill="#0f172a"/>\n  <rect x="377" y="48" width="293" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="523" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">BİYOTEKNOLOJİ (Uygulama ve Ürün)</text>\n  <text x="392" y="98" font-size="12" fill="#14532d">• Geleneksel: Fermantasyon (yoğurt, sirke)</text>\n  <text x="392" y="120" font-size="12" fill="#14532d">• Modern: rDNA ile endüstriyel üretim</text>\n  <text x="392" y="142" font-size="12" fill="#14532d">• İnsülin, büyüme hormonu, aşı, interferon</text>\n  <text x="392" y="164" font-size="12" fill="#14532d">• Dirençli tarım bitkileri ve enzim üretimi</text>\n  <rect x="392" y="182" width="263" height="42" rx="6" fill="#f0fdf4" stroke="#4ade80" stroke-width="1.5"/>\n  <text x="523" y="207" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Odak: Ekonomik ve tıbbi ürün eldesi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MODEL ORGANİZMALARIN TEMEL ÖZELLİKLERİ VE ÖRNEKLERİ</text>\n  <rect x="25" y="45" width="155" height="75" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="102" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Kısa Yaşam Döngüsü</text>\n  <text x="102" y="88" text-anchor="middle" font-size="11" fill="#78350f">Hızlı üreme ve kısa</text>\n  <text x="102" y="104" text-anchor="middle" font-size="11" fill="#78350f">sürede çok döl verme</text>\n\n  <rect x="195" y="45" width="155" height="75" rx="8" fill="#e0e7ff" stroke="#4f46e5" stroke-width="1.8"/>\n  <text x="272" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">Küçük ve Bilinen Genom</text>\n  <text x="272" y="88" text-anchor="middle" font-size="11" fill="#312e81">Gen haritası çıkarılmış,</text>\n  <text x="272" y="104" text-anchor="middle" font-size="11" fill="#312e81">kolay mutasyon izleme</text>\n\n  <rect x="365" y="45" width="155" height="75" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="442" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Ekonomik Bakım</text>\n  <text x="442" y="88" text-anchor="middle" font-size="11" fill="#14532d">Küçük alan ihtiyacı ve</text>\n  <text x="442" y="104" text-anchor="middle" font-size="11" fill="#14532d">düşük besin maliyeti</text>\n\n  <rect x="535" y="45" width="140" height="75" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="605" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Kolay Manipülasyon</text>\n  <text x="605" y="88" text-anchor="middle" font-size="11" fill="#581c87">Gen aktarımına ve</text>\n  <text x="605" y="104" text-anchor="middle" font-size="11" fill="#581c87">deneye elverişlilik</text>\n\n  <rect x="25" y="138" width="650" height="104" rx="10" fill="#ffffff" stroke="#94a3b8" stroke-width="1.8"/>\n  <text x="350" y="160" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">BAŞLICA MODEL ORGANİZMALAR</text>\n  <text x="50" y="185" font-size="12" fill="#1e293b">• <tspan font-weight="bold" fill="#2563eb">Escherichia coli:</tspan> Prokaryot gen klonlaması ve plazmit aktarımında temel model bakteri</text>\n  <text x="50" y="206" font-size="12" fill="#1e293b">• <tspan font-weight="bold" fill="#16a34a">Arabidopsis thaliana:</tspan> Bitki genetiği araştırmalarında kullanılan kısa ömürlü çiçekli bitki</text>\n  <text x="50" y="227" font-size="12" fill="#1e293b">• <tspan font-weight="bold" fill="#dc2626">Drosophila melanogaster &amp; Mus musculus:</tspan> Hayvan genetiği ve insan hastalıkları modelleri</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">REKOMBİNANT DNA TEKNOLOJİSİ İLE GEN KLONLAMASI BASAMAKLARI</text>\n  <rect x="20" y="45" width="145" height="125" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="92" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. İzolasyon</text>\n  <text x="92" y="90" text-anchor="middle" font-size="11" fill="#1e3a8a">Bakteriden plazmit,</text>\n  <text x="92" y="108" text-anchor="middle" font-size="11" fill="#1e3a8a">donör hücreden</text>\n  <text x="92" y="126" text-anchor="middle" font-size="11" fill="#1e3a8a">hedef gen içeren</text>\n  <text x="92" y="144" text-anchor="middle" font-size="11" fill="#1e3a8a">DNA ayrıştırılır.</text>\n\n  <line x1="165" y1="107" x2="185" y2="107" stroke="#475569" stroke-width="2"/>\n  <polygon points="185,102 193,107 185,112" fill="#475569"/>\n\n  <rect x="193" y="45" width="150" height="125" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="268" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. Kesim (Restriksiyon)</text>\n  <text x="268" y="90" text-anchor="middle" font-size="11" fill="#78350f">Plazmit ve hedef gen</text>\n  <text x="268" y="108" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">aynı restriksiyon</text>\n  <text x="268" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">endonükleaz</text>\n  <text x="268" y="144" text-anchor="middle" font-size="11" fill="#78350f">enzimiyle kesilir.</text>\n\n  <line x1="343" y1="107" x2="363" y2="107" stroke="#475569" stroke-width="2"/>\n  <polygon points="363,102 371,107 363,112" fill="#475569"/>\n\n  <rect x="371" y="45" width="145" height="125" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="443" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">3. Birleştirme (Ligaz)</text>\n  <text x="443" y="90" text-anchor="middle" font-size="11" fill="#14532d">Hedef gen ve plazmit</text>\n  <text x="443" y="108" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">DNA Ligaz enzimiyle</text>\n  <text x="443" y="126" text-anchor="middle" font-size="11" fill="#14532d">bağlanarak rDNA</text>\n  <text x="443" y="144" text-anchor="middle" font-size="11" fill="#14532d">oluşturulur.</text>\n\n  <line x1="516" y1="107" x2="536" y2="107" stroke="#475569" stroke-width="2"/>\n  <polygon points="536,102 544,107 536,112" fill="#475569"/>\n\n  <rect x="544" y="45" width="136" height="125" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="612" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">4. Aktarım &amp; Kültür</text>\n  <text x="612" y="90" text-anchor="middle" font-size="11" fill="#581c87">rDNA bakteriye</text>\n  <text x="612" y="108" text-anchor="middle" font-size="11" fill="#581c87">aktarılır, bakteri</text>\n  <text x="612" y="126" text-anchor="middle" font-size="11" fill="#581c87">bölündükçe gen</text>\n  <text x="612" y="144" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">çoğaltılır (klonlanır).</text>\n\n  <rect x="20" y="185" width="660" height="58" rx="8" fill="#f1f5f9" stroke="#64748b" stroke-width="1.5"/>\n  <text x="350" y="207" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">BİYOGÜVENLİK VE BİYOETİK İLKELERİ</text>\n  <text x="350" y="228" text-anchor="middle" font-size="11" fill="#334155">GDO\'lu ürünlerin biyoçeşitliliğe etkisinin kontrolü (Biyogüvenlik) • İnsan onuru ve genetik mahremiyetin korunması (Biyoetik)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
